--[[
	Midnight Helper — Brazilian Portuguese locale shell (Phase B).
	Load order: after esES.lua, before nlNL.lua.

	Non-advisor keys inherit from enUS where not overridden.
	GUIDE_ADVISOR_* and per-spec GUIDE_GEAR_*: GuideAdvisor.lua (Phase C).
	Delve tip bodies: DelveTips.lua (merged at load).
]]

local _, ns = ...

ns._mhLocales = ns._mhLocales or {}

-- Locale-gating (Spec 11 3a): only build this pack when the client is ptBR.
-- enUS + nlNL always load, so auto-detect and forced Dutch keep working; forcing
-- ptBR on another client shows a login notice and loads once the client is ptBR.
if GetLocale() ~= "ptBR" then
	return
end

