	DELVELOG_LBL_DEATHS = "Mortes:",
	DELVELOG_LBL_KEY = "Chave",
	DELVELOG_TOTAL_TIME = "Tempo total:",
	INFO_DRAWER_BODY_DELVELOG = "O Registro de Covas anota cada cova de Midnight que você completa neste personagem. Clique em uma cova para expandir as corridas recentes. Cada corrida mostra nível, tempo de conclusão, mortes, se você usou uma Chave de Cofre Restaurada e o chefe final. O rastreamento roda em segundo plano; esta aba não precisa estar aberta.",
	TAB_WORLD = "Void & Rituals",
	TAB_EVENTS = "Eventos",
	EVENTS_SUBTITLE = "Todos os eventos de mundo do Midnight: o que está acontecendo agora e o que vem nas próximas 24 horas. Clique em um evento ativo para traçar uma rota; passe o mouse para ver o que é e o que recompensa.",
	EVENTS_NONE = "Nenhum evento de mundo visível agora — o agendador pode ainda estar carregando. Tente de novo em alguns segundos.",
	WORLD_EVENTS_HEADER = "Eventos de mundo",
	WORLD_EVENTS_NOW = "Agora",
