	EVENT_INFO_REWARD_LABEL = "Recompensas:",
	EVENT_INFO_CLICK_HINT = "Clique para traçar uma rota.",
	EVENT_INFO_STORMARION_DESC = "Defesa de torre em Voidstorm na Stormarion Citadel — começa a cada 30 minutos. Segure as ondas junto com todos na zona.",
	EVENT_INFO_STORMARION_REWARD = "Cada run concluída: um Victorious Stormarion Cache (Stormarion Cores, Voidlight Marl, ouro). Sua primeira conclusão da semana dá o Pinnacle Cache, maior, e renome com a The Singularity. Os dois baús podem dar a montaria Contained Stormarion Defender e o mascote Kai.",
	EVENT_INFO_HARANIR_DESC = "Um evento de história mais calmo em Harandar. Pegue a missão semanal 'Lost Legends', escolha uma relíquia e jogue sua linha de missões (dá para fazer solo).",
	EVENT_INFO_HARANIR_REWARD = "Um baú semanal, reputação Hara'ti e um item de decoração ligado à sua relíquia. Encontrar todos os objetos de lore nas histórias de relíquias dá o título 'Chronicler of the Haranir'.",
	EVENT_WEEKLY_DONE = "semanal feita",
	EVENT_WEEKLY_TURNIN = "semanal: entregar!",
	EVENT_WEEKLY_ACTIVE = "semanal: em andamento",
	EVENT_WEEKLY_TODO = "semanal disponível",
	EVENT_WEEKLY_LABEL = "Semanal:",
	MODEL_PREVIEW_HINT = "Arraste para girar · role para dar zoom",
	MODEL_PREVIEW_SPIN = "Girar",
	MODEL_PREVIEW_RESET = "Redefinir",
	MODEL_PREVIEW_REWARDS_HINT = "Shift+clique: ver recompensas",
	WORLD_SUBTITLE = "Conteúdo de mundo semanal de Midnight em Quel'Thalas. Um Local ritual fica ativo em uma zona e o Vazio assalta outra — ambos compartilham o centro do Bazar, os Reconhecimentos de Campo e o renome.",
	INFO_DRAWER_BODY_WORLD = "Void & Rituals reúne os dois sistemas de mundo rotativos de Midnight. Locais rituais: interrompa o local ativo (ícone roxo) no seu obelisco. Assaltos do Vazio: limpe Golpes do Vazio na zona ativa para ativar uma Incursão do Vazio. Ambos dão Reconhecimentos de Campo, preenchem sua linha de mundo do Grande Cofre e alimentam o renome comum de Locais rituais. Ambas as semanais são pegas no centro do Bazar em Luenargente.",
	TAB_REFERENCE = "Básico",
	REF_PANEL_INTRO = "Explicações simples sobre sistemas de endgame. Mais tópicos aparecerão aqui com o tempo.",
	INFO_DRAWER_BODY_REFERENCE = "Guias para iniciantes: Crests, onde gastar e bônus de bando. Mais tópicos (profissões, etc.) virão depois.",
	TAB_SMC = "Silvermoon City",
	TAB_PROFESSIONS = "Profissões",
	TAB_GUIDE = "Guias de nivelamento",
	TAB_MACROS = "Macros",
	TAB_CONSUMABLES = "Consumíveis",
	TAB_ACADEMY = "Academia de papéis",
	TAB_TOOLBOX = "Ferramentas",
	-- Artigos do códice do patch 12.0.7
	CODEX_127_SHOWDOWNS_TITLE = "Showdowns: Naigtal e Val (12.0.7)",
	CODEX_127_SHOWDOWNS_BODY = "Um portal no Voidstorm (Howling Ridge), ou o portal permanente no Bazaar de Silvermoon, leva a um de dois mundos do Caos que trocam toda semana: o fúngico Naigtal ou o gélido Val. Ambos oferecem missões de mundo, raros, eventos de zona e um chefe mundial (Nexus-Captain Leth'ir / Imperator Pertinax). A semanal de Showdown concede um Riftstalker's Cache e conta para a fileira World do Grande Cofre. A Heroic World Tier opcional aumenta dificuldade e recompensas — escolha no portal. Comece com Riftblade Maella em Silvermoon. Na Série 2 isto é conteúdo de recuperação: bom para alts e para personagens que acabaram de chegar ao nível 90, não para o seu melhor equipamento.",
	CODEX_127_SPOREFALL_TITLE = "Raide Sporefall (12.0.7)",
	CODEX_127_SPOREFALL_BODY = "Raide de chefe único em Harandar: Rotmire, um gigante fúngico. É uma raide da Série 1: o equipamento dela (LFR 259 / Normal 272 / Heroico 285 / Mítico 298) é mais baixo que a mesma dificuldade na raide da Série 2, então você vai lá pela montaria e pelo visual, não por melhorias. O Mítico é flexível com 15-25 jogadores. Pegue um Delicious Sporesnack uma vez por semana (por conta) em qualquer dificuldade — junte quatro para formar a montaria Luminous Sporeglider.",
	CODEX_127_FOLIO_TITLE = "Omnium Folio e Runas (12.0.7)",
	CODEX_127_FOLIO_BODY = "Novo sistema de poder que não ocupa espaço de equipamento. Desbloqueie pela linha de missões do Sunstrider Omnium com Umbric e Rommath em Quel'Danas. A cada semana, a missão 'Seeking Knowledge' concede um Mote of Omnial Inquiry para abrir uma das cinco fileiras de runas; as runas trocam livremente fora de combate.",
	CODEX_127_TIMEWAYS_TITLE = "Turbulent Timeways V (30 jun - 11 ago)",
	CODEX_127_TIMEWAYS_BODY = "Maratona de Caminhada Temporal com seis masmorras de Dragonflight. Faça quatro masmorras numa semana para o buff Mastery daquela semana; consiga Mastery em quatro semanas distintas para a montaria Spawn of Vyranoth.",
	CODEX_127_RITUALRENOWN_TITLE = "Renome dos Locais Rituais (12.0.5)",
	CODEX_127_RITUALRENOWN_BODY = "Os Locais Rituais têm uma trilha de Renome por conta (8 níveis) na janela Journeys. Subir de nível enriquece cada local: Regeneration Orbs que curam, depois inimigos raros (nível 4), santuários de bônus (nível 5), tesouros maiores (nível 7) e elites raros (nível 8) — todos com espólios extra. Também desbloqueia itens de vendedores em Lua Prateada: decoração de lar do Vazio (nível 3, Rae'ana), mascotes (nível 6, Sergeant Vornin) e a montaria Void-Touched Hawkstrider (nível 8, Sergeant Vornin). Cada recompensa é de bando de guerra (Warband), então o teu progresso conta para a conta toda. Clique nos Loa Shrines brilhantes dentro de um site para um buff de atributo de 60 minutos (ex.: +10% de acerto crítico).",
	TAB_BETA_BADGE = "Beta",
	TAB_BETA_TOOLTIP_TITLE = "Em desenvolvimento",
	TAB_BETA_TOOLTIP_BODY = "Esta guia está em beta inicial — o conteúdo está incompleto, pode mudar com frequência e ainda não está pronto para uso completo.",
	TAB_ADDONS = "Complementos",
	SEARCH_CHAT_TAB_ACADEMY = "Guia aberta: Academia de Funções",
	ACADEMY_SUBTITLE = "Um curso curto de tankar, curar e fazer DPS em grupo: como pensar, o que preparar primeiro e um caminho tranquilo até as masmorras.",
	ACADEMY_TRACK_TANK = "Trilha do tanque",
	ACADEMY_TRACK_HEAL = "Trilha de cura",
	ACADEMY_CLASS_FMT = "Conectado: %s - %s. O cartão da sua spec: /mh play",
	ACADEMY_CLASS_OPEN_CHAT_FMT = "Macros abertas para %s - %s. Verifique também os consumíveis para frascos e potes.",
	ACADEMY_PREF_TITLE = "Lista de verificação pré-voo (marque quando estiver pronto)",
	ACADEMY_PREF_HINT = "As marcações ficam salvas nas suas configurações. Macros e Consumíveis ficam na sala Ferramentas.",
	ACADEMY_PREF_TANK_INTERRUPT = "Minha interrupção na barra: o próprio botão, ou uma macro pronta (guia Macros)",
	ACADEMY_PREF_TANK_DEFENSIVE = "Uma defensiva pronta (seu cartão: /mh play -> Continue vivo)",
	ACADEMY_PREF_TANK_CONSUMABLES = "Frasco/pote pronto (guia Consumíveis)",
	ACADEMY_PREF_TANK_TAUNT = "Conheço minha tecla de provocar (testei uma vez num boneco de treino - Luaprata tem)",
	ACADEMY_PREF_HEAL_MACROS = "Macros de recuperação de mouse/foco (guia Macros)",
	ACADEMY_PREF_HEAL_DEFENSIVE = "Defensiva pessoal na barra (seu cartão: /mh play -> Continue vivo)",
	ACADEMY_PREF_HEAL_CONSUMABLES = "Pote/frasco de mana (guia Consumíveis)",
	ACADEMY_PREF_HEAL_PRACTICE = "Curei um amigo uma vez clicando no quadro dele",
	ACADEMY_TANK_INTRO_TITLE = "Mentalidade de tanque",
	ACADEMY_TANK_INTRO_BODY = "Seu trabalho: fazer os inimigos baterem em você, não no seu grupo, e definir o ritmo, não causar o maior dano.\n\nUm pull tranquilo vale mais que uma ordem de botões perfeita com o grupo morto. Se ajudar, anuncie os pulls em voz alta: \"pull em 3\".",
	ACADEMY_TANK_PULL_TITLE = "Durante uma puxada (primeiros 10 segundos)",
	ACADEMY_TANK_PULL_BODY = "1. Pegue o pack: acerte todos com seus ataques que atingem muitos inimigos de uma vez (AoE). Provoque só o que correr para outra pessoa.\n2. Vire os inimigos de costas para o grupo quando puder: alguns inimigos acertam tudo o que está na frente deles, e senão isso acerta o seu grupo também.\n3. Aperte uma defensiva antes do dano grande ou no começo de um pull grande, não quando sua vida já está baixa. Uma de cada vez; guarde uma grande para a pancada mais forte.\n4. Interrompa o feitiço que mais machuca (muitas vezes uma cura ou uma pancada grande).\n\nVocê não precisa apertar todos os botões ao mesmo tempo.",
	ACADEMY_TANK_WIPE_TITLE = "Quando dá errado",
	ACADEMY_TANK_WIPE_BODY = "Um wipe é informação, não um veredito. Pergunte: \"Eu estava muito à frente?\" ou \"Apertei uma defensiva antes da pancada grande?\"\n\nRecupere o fôlego, coma e beba, tente de novo.",
	ACADEMY_TANK_DUNGEON_TITLE = "Sua primeira masmorra normal (depois de uma de seguidor)",
	ACADEMY_TANK_DUNGEON_BODY = "Vá com amigos ou a sua guilda se der; senão, um grupo aleatório também serve. Convide os amigos antes: clique com o botão direito no nome deles no chat -> Convidar, ou digite /inv e o nome. Depois o líder do grupo aperta \"Encontrar grupo\".\n\nAntes de \"Encontrar grupo\", marque o ícone de Tanque (curandeiros: o ícone de Cura). Sem uma função marcada, o botão não funciona. Não é o líder? Quando o líder apertar \"Encontrar grupo\", aparece \"Confirme sua função:\": marque sua função e clique em \"Aceitar\".\n\nVá devagar nos pulls: dois packs pequenos são melhores que um pull enorme de vários packs de uma vez.\n\nFique de olho na mana do curandeiro; faça pausas entre os pulls. Tudo bem pedir CC ou \"nada de pull grande ainda\".",
	ACADEMY_TANK_RAID_TITLE = "Raides e LFR (mais tarde)",
	ACADEMY_TANK_RAID_BODY = "O LFR é a entrada suave nas raides: perdoa bastante e tem muitos curandeiros. Preste atenção nos ataques grandes do chefe e fique no lugar certo.\n\nTankar raide mítica não é o próximo passo: primeiro fique à vontade no heroico/LFR.",
	ACADEMY_TANK_CHAT_TITLE = "Bate-papo de festa",
	ACADEMY_CHAT_HINT = "Clique numa linha (ou no ícone de cópia) e aperte Ctrl+C. Aperte Enter: o chat abre em Diz, que só as pessoas perto de você veem. Para o seu grupo, digite antes /p e um espaço; numa masmorra do Localizador de Grupos, digite /i. Depois Ctrl+V para colar e Enter para enviar. Ponha o nome do feitiço do inimigo onde está [nome do feitiço].",
	ACADEMY_CHAT_COPY_TIP = "Selecione esta linha (Ctrl+C)",
	ACADEMY_TANK_CHAT_BODY = "\"Ainda aprendendo tanque - vá devagar, por favor.\"\n\"Puxando 3...\"\n\"Preciso de um descanso para mana.\"\n\"Interrompa em [nome do feitiço] - eu tenho o próximo.\"\n\"Mais uma tentativa - eu conheço esse puxão agora.\"",
	ACADEMY_TANK_LADDER_TITLE = "Escada de ansiedade (ordem recomendada)",
	ACADEMY_TANK_LADDER_BODY = "1. Elites (inimigos mais fortes) lá fora no mundo, com um amigo\n2. Delves (instância menor - aba Profundidades)\n3. Masmorra de seguidor: PNJs completam o grupo (nível 80-90). Localizador de Grupos -> Loc. de Masmorras -> Masmorras de seguidor\n4. Masmorra normal com pessoas em quem você confia\n5. Heroico / LFR quando estiver confortável\n\nFique em cada etapa até ela parecer chata, não assustadora. Depois suba para a próxima.",
	ACADEMY_TANK_BOTH_TITLE = "Aprender a curar também?",
	ACADEMY_TANK_BOTH_BODY = "A trilha de DPS é a segunda função mais suave: seus botões, interrupções e onde você fica, sem um grupo dependendo de você. Curar é o salto maior, mas você já sabe ler os pulls, e isso é metade.\n\nEscolha uma função principal nas masmorras por um tempo e pratique a outra em delves ou lá fora no mundo. Trocar de função no mesmo grupo de M+ com desconhecidos dobra o estresse; dominar uma função primeiro dá confiança para a segunda.",
	ACADEMY_HEAL_INTRO_TITLE = "Curar mentalidade",
	ACADEMY_HEAL_INTRO_BODY = "Você não é responsável por todos com 100% de saúde o tempo todo.\n\nSeu trabalho é fazer a triagem: manter o tanque vivo, salvar a pessoa prestes a morrer e depois o resto. Alguns danos são normais – a cura excessiva do pânico esvazia mana.",
	ACADEMY_HEAL_TRIAGE_TITLE = "Triagem (quem primeiro?)",
	ACADEMY_HEAL_TRIAGE_BODY = "1. Você (se estiver morrendo: curandeiro morto não cura ninguém)\n2. Tanque (se o pack ainda estiver batendo nele)\n3. Qualquer um abaixo de ~40% ou com um debuff mortal\n4. Todos os outros com curas eficientes\n\nAlguém prestes a morrer: primeiro uma cura que chega na hora (uma instantânea, cujo tooltip diz \"Instantâneo\", ou sua cura rápida). Muito dano e tempo para lançar: sua cura grande (druida: sua cura direta com tempo de lançamento). Calmo: uma cura que custa pouca mana (o tooltip mostra o custo).",
	ACADEMY_HEAL_WIPE_TITLE = "Quando dá errado",
	ACADEMY_HEAL_WIPE_BODY = "\"Eu poderia ter salvado o tanque?\" é a pergunta útil, não \"por que o DPS ficou no chão ruim?\"\n\nSe a mana acabou, use feitiços mais eficientes na próxima vez. Um wipe não quer dizer que você não sabe curar.",
	ACADEMY_HEAL_DUNGEON_TITLE = "Sua primeira masmorra normal (depois de uma de seguidor)",
	ACADEMY_HEAL_DUNGEON_BODY = "Com amigos se der, senão com um grupo aleatório (as etapas acima mostram como). Marque o ícone de Cura antes de apertar \"Encontrar grupo\".\n\nDiga ao grupo que você está aprendendo. Fique perto o bastante do tanque para suas curas chegarem nele (no alcance); deixe o DPS levar um arranhão antes de gastar mana.\n\nEntre os pulls: beba, passe seus buffs, respire. Você pode dizer “OOM, 5 seg”.",
	ACADEMY_HEAL_RAID_TITLE = "Raides e LFR (mais tarde)",
	ACADEMY_HEAL_RAID_BODY = "LFR: o dano no raide inteiro fica previsível depois de um wipe. Aprenda quando vêm as pancadas grandes do chefe (a linha do tempo Habilidades do Chefe mostra), não as barras de cada jogador.\n\nCurar em raide usa a mesma triagem: primeiro os cooldowns para o tanque e para o raide.",
	ACADEMY_HEAL_CHAT_TITLE = "Bate-papo de festa",
	ACADEMY_HEAL_CHAT_BODY = "\"Aprendendo a curar - aviso quando a mana estiver baixa.\"\n\"O tanque é prioridade - grite se precisar de uma pausa.\"\n\"Cura grande em você - fique de olho na sua vida.\"\n\"OOM, 5 seg entre os pulls.\"\n\"Essa foi culpa minha - no próximo pull guardo mais para o tanque.\"",
	ACADEMY_HEAL_LADDER_TITLE = "Escada de ansiedade (ordem recomendada)",
	ACADEMY_HEAL_LADDER_BODY = "1. Cure um amigo lá fora no mundo (não numa masmorra)\n2. Delves com um grupo pequeno\n3. Masmorra de seguidor: PNJs completam o grupo (nível 80-90). Localizador de Grupos -> Loc. de Masmorras -> Masmorras de seguidor\n4. Masmorra normal com amigos pacientes\n5. Raide LFR / heroica quando estiver pronto\n\nDelves são o passo mais suave para o conteúdo instanciado.",
	ACADEMY_HEAL_BOTH_TITLE = "Tanque de aprendizagem também?",
	ACADEMY_HEAL_BOTH_BODY = "A trilha de DPS é a segunda função mais suave: só seus botões, interrupções e onde você fica, sem pressão no grupo. Como tanque você espera menos por um grupo de masmorra, assim que tankar parecer menos assustador.\n\nDuas funções numa semana em grupos com desconhecidos é muito: escolha uma como \"principal\" para ter menos medo.",
	INFO_DRAWER_BODY_ACADEMY = "Academia de papéis: trilhas de tanque, cura e DPS, lista de preparação, notas de masmorra e raide, e frases para o chat do grupo. Abra a qualquer momento com /mh academy (ou /mh academy tank, /mh academy heal). Macros e Consumíveis ficam na sala Ferramentas.",
