	LAYOUT_KEY_ROLE_TOOLTIP_FMT = "|cffffcc00%s|r",
	LAYOUT_KEY_BIND_LAYER_FMT = "|cffe0e070%s|r — %s",
	LAYOUT_KEY_MOVEMENT_TOOLTIP = "Mova seu personagem: W para frente, S para trás, A/D strafe, mouse para virar. WoW os usa por padrão – mantenha-os livres para caminhar.",
	LAYOUT_KEY_TAB_TOOLTIP = "A guia alterna os alvos. WoW usa-o por padrão – mantenha Tab livre para que você possa escolher o inimigo certo rapidamente em combate.",
	LAYOUT_KEY_PREFERRED_TOOLTIP = "Dica de Midnight: mantenha esta tecla livre para feitiços, macros ou combos Shift/Ctrl/Alt – a mesma ideia das teclas F acesas em suas barras de ação.",
	LAYOUT_LEGEND = "|cff33ff61Green|r = mover (W A S D).\n|cffe0e070Gold|r = feitiços e atalhos neste mapa.\n|cff59d9ffTab|r = trocar de alvo rapidamente.\n|cff888888Grey|r = não neste mapa inicial.",
	LAYOUT_KEY_HIGHLIGHT_FROM_GUIDE = "|cffe0e070Aberto no seu guia de nivelamento – esta chave está no mapa Midnight.|r",
	MODULE_PLACEHOLDER = "Espaço reservado para módulo — o conteúdo de \"%s\" será montado aqui.",
	INFO_DRAWER_TOGGLE_SHOW = "Informações",
	INFO_DRAWER_TOGGLE_HIDE = "Fechar",
	INFO_DRAWER_TITLE_FMT = "%s - Como usar",
	INFO_DRAWER_BODY_DELVES = "Centro de comando Midnight Delves para seu personagem atual.\n\nExpanda Grande Cofre para rastreamento de recompensas semanais ou Midnight Delves para moedas da temporada (Restored Coffer Keys, Shards semanais, Undercoins), Delver's Journey / renome e a lista completa de Delve com detecção abundante ao vivo de POIs do mapa.\n\nNavegação: clique com o botão direito em uma linha para direcionar para a entrada. |cffffcc00TomTom (recomendado)|r adiciona a seta do mapa e a fila do waypoint. |cff00ff00Travel Assistant|r (pop-up quando você está longe) mostra os atalhos do Hearthstone e do portal central e funciona |cffffff00sem|r TomTom.\n\nO Find Nearest Bountiful requer a instalação do TomTom.",
	INFO_DRAWER_BODY_ACCOUNT = "Lista de vários personagens armazenada localmente por este complemento (variáveis salvas no seu PC, não na sincronização com a nuvem da Blizzard).\n\nCada linha lista Chaves, Fragmentos, Undercoins, eco de profissões e um resumo compacto do Grande Cofre com dicas de ferramentas ricas; seu personagem logado é destacado e a classificação favorece a utilidade.\n\nAs linhas são atualizadas no login e na moeda/eventos semanais. Excluir remove apenas dados de instantâneos adicionais – nunca seu personagem WoW real.",
	INFO_DRAWER_BODY_RARES = "Raros do mundo Midnight por zona (Eversong, Zul'Aman, Harandar, Voidstorm).\n\nEscolha uma zona à esquerda. Verde = feito esta semana NESTE personagem (um alt ainda pode lootear); UP verde = vignette no spawn (provavelmente ativo); traço cinza = não no mapa agora.\n\nRare mais próximo = um pin; Gerar rota = todos os raros abertos no TomTom. Status UP é aproximado — abra o mapa da zona ou aproxime-se se tiver dúvida.",
	RARES_TITLE = "Raros Midnight",
	RARES_SUBTITLE_FMT = "%d/%d feitos esta semana neste personagem · %d visíveis no mapa (estrela prateada)",
	RARES_EMPTY_ZONE = "Nenhuma lista de raros para esta zona.",
	RARES_BTN_NEAREST = "Rare mais próximo",
	RARES_BTN_ROUTE = "Gerar rota",
	RARES_NEAREST_ROUTE = "|cffffff78Midnight Helper:|r TomTom: rare mais próximo — %s",
	RARES_NEAREST_NONE = "Nenhum rare incompleto restante nesta zona.",
	RARES_NEAREST_NO_TRAVEL = "Travel Assistant indisponível (módulo Profundidades não carregado).",
	RARES_ROUTE_DONE_FMT = "%d/%d raros incompletos no TomTom. %s",
	RARES_ROUTE_ORDER_NEAR = "Ordem: o mais próximo primeiro, depois o seguinte a cada passo.",
	RARES_ROUTE_ORDER_LIST = "Ordem: ordem da lista (posição indisponível).",
	RARES_TAG_UP = "UP",
	RARES_TAG_DOWN = "—",
	RARES_TIP_DONE = "Feito neste personagem — abre de novo no próximo reset. Outro personagem seu ainda pode lootear.",
